import hashlib
import json
from pathlib import Path
import statistics
import subprocess
import sys
import time

from fpdf import FPDF
import pymupdf
from aspose.words_foss.pdf_writer.font import close_fonts

ROOT = Path('/Users/sheny/Developer/code/Aspose.Words-FOSS-for-Python')
STYLES = {'': 'Regular', 'B': 'Bold', 'I': 'Oblique', 'BI': 'BoldOblique'}

def render(candidate, all_styles):
    pdf = FPDF()
    start = time.perf_counter()
    try:
        for style, face in STYLES.items():
            if not all_styles and style:
                continue
            path = Path(f'/tmp/DocumentSansSC-{face}-zopfli.woff') if candidate else ROOT / f'aspose/words_foss/pdf_writer/fonts/DocumentSansSC-{face}.woff'
            pdf.add_font('DocumentSansSC', style, path)
        load = time.perf_counter() - start
        pdf.add_page()
        for style in STYLES if all_styles else ['']:
            pdf.set_font('DocumentSansSC', style, 14)
            pdf.multi_cell(0, 10, '简体中文 繁體中文 ABC abc 123 €，。', new_x='LMARGIN', new_y='NEXT')
        data = bytes(pdf.output())
        elapsed = time.perf_counter() - start
    finally:
        close_fonts(pdf)
    with pymupdf.open(stream=data, filetype='pdf') as doc:
        pages = [{'text': page.get_text(), 'words': page.get_text('words'), 'pixels_sha256': hashlib.sha256(page.get_pixmap(matrix=pymupdf.Matrix(2, 2)).samples).hexdigest()} for page in doc]
    return {'load_seconds': load, 'render_seconds': elapsed, 'pages': pages, 'pdf_bytes': len(data)}

if len(sys.argv) > 1:
    print(json.dumps(render(sys.argv[1] == 'candidate', sys.argv[2] == 'all')))
else:
    result = {'python': sys.version, 'samples': {}, 'probe_source': Path(__file__).read_text()}
    for mode in ['regular', 'all']:
        samples = {'baseline': [], 'candidate': []}
        for iteration in range(5):
            for kind in (['baseline', 'candidate'] if iteration % 2 == 0 else ['candidate', 'baseline']):
                sample = json.loads(subprocess.check_output([sys.executable, __file__, kind, mode], text=True))
                samples[kind].append(sample)
        assert all(sample['pages'] == samples['baseline'][0]['pages'] for runs in samples.values() for sample in runs)
        result['samples'][mode] = samples
        result[mode] = {kind: {metric: statistics.median(sample[metric] for sample in runs) for metric in ['load_seconds', 'render_seconds']} for kind, runs in samples.items()}
    Path('/tmp/docweave-woff-validation.json').write_text(json.dumps(result, indent=2) + '\n')
    print(json.dumps({mode: result[mode] for mode in ['regular', 'all']}))
